# Index de recherche (forme normalisée -> entrée)
_INDEX: dict[str, dict] | None = None


def _norm(s: str) -> str:
    from unidecode import unidecode

    s = unidecode((s or "").lower()).replace("'", " ").replace("’", " ").replace("-", " ")
    return " ".join(s.split())


def _index() -> dict[str, dict]:
    global _INDEX
    if _INDEX is None:
        idx: dict[str, dict] = {}
        for t in TRADES:
            for form in [t["key"], t["label"], t.get("feminine") or "", *t.get("aliases", [])]:
                if form:
                    idx.setdefault(_norm(form), t)
                    # pluriels simples
                    idx.setdefault(_norm(form) + "s", t)
        _INDEX = idx
    return _INDEX


def lookup_trade(raw: str | None) -> dict | None:
    """Retrouve un métier du dictionnaire à partir d'un libellé libre (« tisserand en coton », « Manœuvre »…)."""
    if not raw:
        return None
    n = _norm(raw)
    for prefix in ("ancien ", "ex ", "maitre ", "compagnon ", "garcon ", "apprenti "):
        if n.startswith(prefix) and n[len(prefix):] in _index():
            return _index()[n[len(prefix):]]
    idx = _index()
    if n in idx:
        return idx[n]
    # Plus longue forme connue présente comme suite de mots dans le libellé
    words = f" {n} "
    best: tuple[int, dict] | None = None
    for form, t in idx.items():
        if len(form) >= 4 and f" {form} " in words and (best is None or len(form) > best[0]):
            best = (len(form), t)
    return best[1] if best else None


def split_occupations(raw: str | None) -> list[str]:
    """« tisserand, journalier » / « tisserand et journalier » -> ['tisserand', 'journalier']."""
    import re

    if not raw:
        return []
    parts = re.split(r"\s*(?:[,;/]|\bpuis\b|\bet\b)\s*", raw.strip())
    return [p.strip(" .") for p in parts if p and p.strip(" .")]
